const clamp01 = (value) => Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));
const smooth01 = (value) => { const x = clamp01(value); return x * x * (3 - 2 * x); };
const slot4 = (value) => ((Math.floor(Number.isFinite(value) ? value : 0) % 4) + 4) % 4;
function rhythm(phase, stress, critical, slot, normalMin, criticalMin, reducedMotion = false, reducedFlash = false) { const s = slot4(slot), shifted = (clamp01(phase) + s * .25) % 1, triangle = 1 - Math.min(1, Math.abs(shifted - .5) * 2), peak = smooth01(triangle), load = clamp01(stress), base = reducedMotion ? .72 : .54, amplitude = reducedMotion ? .14 : .42, flash = reducedFlash ? .94 : 1, minimum = critical ? criticalMin : normalMin, secondaryScale = clamp01(Math.max(minimum, base + peak * amplitude - load * (critical ? .08 : .16)) * flash); return { slot: s, phase: shifted, peak, primaryScale: 1, secondaryScale, presentationOnly: true }; }
export function projectileThreatRhythmPresentation(input, reducedMotion = false, reducedFlash = false) { return rhythm(input.phase, input.stress, input.critical, input.slot, .4, .58, reducedMotion, reducedFlash); }
export function impactThreatRhythmPresentation(input, reducedMotion = false, reducedFlash = false) { return rhythm(input.phase, input.stress, input.critical, input.slot, .36, .54, reducedMotion, reducedFlash); }
export function hazardThreatRhythmPresentation(input, reducedMotion = false, reducedFlash = false) { return rhythm(input.phase, input.stress, input.critical, input.slot, .38, .56, reducedMotion, reducedFlash); }
export function safeLaneThreatRhythmPresentation(input, reducedMotion = false, reducedFlash = false) { return { ...rhythm(input.phase, input.stress, input.critical, input.slot, .46, .64, reducedMotion, reducedFlash), safeLaneScale: 1, presentationOnly: true }; }
export function specialistThreatRhythmPresentation(input, reducedMotion = false, reducedFlash = false) { return rhythm(input.phase, input.stress, input.critical, input.slot, .38, .58, reducedMotion, reducedFlash); }
export function threatRhythmBudgetPresentation(input, reducedMotion = false, reducedFlash = false) { const active = Math.max(0, Math.floor(input.activeCount)), load = clamp01(input.stress), critical = clamp01(Math.max(0, input.criticalCount) / 3), maxConcurrentPeaks = active >= 10 ? 1 : active >= 5 ? 2 : 3, secondaryScale = Math.max(.54, 1 - load * .28 - critical * .04) * (reducedMotion ? .98 : 1) * (reducedFlash ? .96 : 1); return { maxConcurrentPeaks, primaryScale: 1, secondaryScale: clamp01(secondaryScale), safeLaneScale: 1, presentationOnly: true }; }
